// src/storage.ts
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { join } from "node:path";
var DEFAULT_CONFIG = {
  activeHours: [9, 22],
  timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
  dailyTarget: 5,
  vocabTags: ["ielts"]
};
function defaultProgress() {
  return {
    level: 7,
    // cefrCeiling(7)=B2 — matches the IELTS dataset (all words are B2–C1)
    mastered: [],
    weights: {},
    lastPushTime: 0,
    config: { ...DEFAULT_CONFIG }
  };
}
function progressPath(stateDir, userId) {
  const safe = userId.replace(/[^a-zA-Z0-9_\-@.:]/g, "_");
  return join(stateDir, "vocab-progress", `${safe}.json`);
}
async function ensureDir(stateDir) {
  await mkdir(join(stateDir, "vocab-progress"), { recursive: true });
}
async function readJson(path, fallback) {
  try {
    return JSON.parse(await readFile(path, "utf8"));
  } catch {
    return fallback;
  }
}
async function loadProgress(stateDir, userId) {
  return readJson(progressPath(stateDir, userId), defaultProgress());
}
async function saveProgress(stateDir, userId, progress) {
  await ensureDir(stateDir);
  await writeFile(progressPath(stateDir, userId), JSON.stringify(progress), "utf8");
}

